-- =========================================================
-- Database Script for Employee Management System
-- Project: Java Swing + JDBC + MySQL
-- Modules: Authentication + Employee Management + Payroll
-- Contains 200 Complete Employee Records
-- =========================================================

-- 1. Create the Database
CREATE DATABASE IF NOT EXISTS employee_management;

-- 2. Use the Database
USE employee_management;

-- 3. Create 'users' table for Role-Based Login (Admin / Employee)
CREATE TABLE IF NOT EXISTS users (
    user_id INT PRIMARY KEY AUTO_INCREMENT,
    username VARCHAR(50) UNIQUE NOT NULL,
    password VARCHAR(100) NOT NULL,
    role VARCHAR(20) NOT NULL -- 'ADMIN' or 'EMPLOYEE'
);

-- 4. Create 'employees' table for storing Employee records (including Benefits)
CREATE TABLE IF NOT EXISTS employees (
    employee_id VARCHAR(20) PRIMARY KEY,
    employee_name VARCHAR(100) NOT NULL,
    gender VARCHAR(10) NOT NULL,
    dob DATE NOT NULL,
    department VARCHAR(50) NOT NULL,
    designation VARCHAR(50) NOT NULL,
    salary DOUBLE NOT NULL,
    phone VARCHAR(15) NOT NULL,
    email VARCHAR(100) NOT NULL,
    address TEXT NOT NULL,
    health_insurance BOOLEAN DEFAULT FALSE,
    provident_fund BOOLEAN DEFAULT FALSE,
    company_transport BOOLEAN DEFAULT FALSE,
    meal_allowance BOOLEAN DEFAULT FALSE
);

-- 5. Create 'payroll' table for Employee Payroll Management
CREATE TABLE IF NOT EXISTS payroll (
    payroll_id INT PRIMARY KEY AUTO_INCREMENT,
    employee_id VARCHAR(20) NOT NULL,
    employee_name VARCHAR(100) NOT NULL,
    basic_salary DECIMAL(12,2) NOT NULL DEFAULT 0,
    hra DECIMAL(12,2) NOT NULL DEFAULT 0,
    da DECIMAL(12,2) NOT NULL DEFAULT 0,
    other_allowance DECIMAL(12,2) NOT NULL DEFAULT 0,
    gross_salary DECIMAL(12,2) NOT NULL DEFAULT 0,
    pf DECIMAL(12,2) NOT NULL DEFAULT 0,
    professional_tax DECIMAL(12,2) NOT NULL DEFAULT 0,
    other_deduction DECIMAL(12,2) NOT NULL DEFAULT 0,
    total_deduction DECIMAL(12,2) NOT NULL DEFAULT 0,
    net_salary DECIMAL(12,2) NOT NULL DEFAULT 0,
    pay_month VARCHAR(20) NOT NULL,
    pay_year INT NOT NULL,
    payment_status VARCHAR(20) NOT NULL DEFAULT 'Pending',
    FOREIGN KEY (employee_id) REFERENCES employees(employee_id) ON DELETE CASCADE
);

-- =========================================================
-- 1. Insert Login Users
-- =========================================================
ON DUPLICATE KEY UPDATE role = VALUES(role);

-- =========================================================
-- 2. Insert 200 Employee Records (EMP101 to EMP300)
-- =========================================================
ON DUPLICATE KEY UPDATE employee_name = VALUES(employee_name);

-- =========================================================
-- 3. Insert Sample Payroll Records for All 200 Employees
-- =========================================================
    employee_id, employee_name, basic_salary, hra, da, other_allowance, gross_salary,
    pf, professional_tax, other_deduction, total_deduction, net_salary, pay_month, pay_year, payment_status
)
SELECT
    employee_id,
    employee_name,
    salary AS basic_salary,
    ROUND(salary * 0.20, 2) AS hra,
    ROUND(salary * 0.10, 2) AS da,
    ROUND(salary * 0.05, 2) AS other_allowance,
    ROUND(salary + (salary * 0.20) + (salary * 0.10) + (salary * 0.05), 2) AS gross_salary,
    ROUND(salary * 0.12, 2) AS pf,
    200 AS professional_tax,
    0 AS other_deduction,
    ROUND((salary * 0.12) + 200, 2) AS total_deduction,
    ROUND(salary + (salary * 0.20) + (salary * 0.10) + (salary * 0.05) - (salary * 0.12) - 200, 2) AS net_salary,
    'September' AS pay_month,
    2026 AS pay_year,
    'Paid' AS payment_status
FROM employees
WHERE employee_id BETWEEN 'EMP101' AND 'EMP300'
AND NOT EXISTS (
    SELECT 1 FROM payroll p WHERE p.employee_id = employees.employee_id AND p.pay_month = 'September' AND p.pay_year = 2026
);
